verus! {
    spec fn count_eligible(participations: Seq<int>, k: int) -> int {
        // Count the number of eligible participants
        let mut count = 0;
        let len = participations.len();
        for i in 0..len {
            if participations[i] >= 0 && participations[i] <= 5 {
                if 5 - participations[i] >= k {
                    count += 1;
                }
            }
        }
        count
    }

    fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
        // Precondition: n and k must be in the range [0, 5]
        assert!(n <= 5);
        assert!(k <= 5);
        
        // Limit the number of participants to n
        let len = participations.len();
        let limit = if len < n as usize { len } else { n as usize };

        // Create a sequence of eligible participants
        let mut eligible_participants = Seq::new();
        for i in 0..limit {
            if participations[i] <= 5 {
                if 5 - participations[i] >= k {
                    eligible_participants.push(participations[i] as int);
                }
            }
        }

        // Count the eligible participants
        let eligible_count = count_eligible(eligible_participants, k as int);

        // The maximum number of disjoint teams of 3
        eligible_count / 3
    }
}